<?php
namespace App\Http\Resources;
use Illuminate\Http\Resources\Json\JsonResource;
class TransferResource extends JsonResource { public function toArray($request): array { return ['id'=>$this->id,'transfer_reference'=>$this->transfer_reference,'source_currency_code'=>$this->source_currency_code,'destination_currency_code'=>$this->destination_currency_code,'source_amount_minor'=>(int)$this->source_amount_minor,'recipient_amount_minor'=>(int)$this->recipient_amount_minor,'provider_fee_minor'=>(int)$this->provider_fee_minor,'platform_fee_minor'=>(int)$this->platform_fee_minor,'exchange_rate'=>(string)$this->exchange_rate,'transfer_type'=>$this->transfer_type,'status'=>$this->status,'failure_reason'=>$this->failure_reason,'sandbox_provider_reference'=>$this->sandbox_provider_reference,'sandbox_only'=>(bool)$this->sandbox_only,'beneficiary'=>$this->whenLoaded('beneficiary',fn()=>['id'=>$this->beneficiary->id,'display_name'=>$this->beneficiary->display_name,'beneficiary_type'=>$this->beneficiary->beneficiary_type]),'events'=>$this->whenLoaded('events'), 'receipt'=>$this->whenLoaded('receipt')]; } }
